from __future__ import annotations

def interleave(x: float, y: float, digits: int = 8) -> float:
    """Pair (x, y) in [0,1)^2 into a single real by interleaving decimals,
    a finite witness for the bijection R x R ~ R."""
    dx = [d for d in f"{x:.{digits}f}".split(".")[1]]
    dy = [d for d in f"{y:.{digits}f}".split(".")[1]]
    return float("0." + "".join(a + b for a, b in zip(dx, dy)))

def deinterleave(z: float, digits: int = 8) -> tuple[float, float]:
    frac = f"{z:.{2*digits}f}".split(".")[1]
    return float("0." + frac[0::2]), float("0." + frac[1::2])

if __name__ == "__main__":
    x, y = 0.12345678, 0.87654321
    z = interleave(x, y)
    print("interleaved:", z)
    print("recovered:", deinterleave(z))

