function DIAGONAL(f, S):
    D <- empty set
    for each x in S:
        if x not in f(x):
            add x to D
    # D differs from f(x) at x for every x, so D not in image(f)
    return D

function PAIR(a, b):
    s <- a + b
    return s*(s+1)/2 + b

function UNPAIR(z):
    w <- floor((sqrt(8z+1) - 1) / 2)
    t <- w*(w+1)/2
    b <- z - t
    a <- w - b
    return (a, b)

function CANTOR_TOWER(levels, base):
    tower <- [base]
    for i in 1..levels:
        tower.append(2 ^ tower[-1])   # power-set cardinality
    return tower   # strictly increasing by Cantor's theorem
